keyConcepts.codeExample:
interface DiscountPolicy {
    int apply(int totalCents);
}

class BlackFridayDiscount implements DiscountPolicy {
    public int apply(int totalCents) { return totalCents - totalCents * 30 / 100; }
}

class LoyaltyDiscount implements DiscountPolicy {
    public int apply(int totalCents) { return totalCents - totalCents * 5 / 100; }
}

int finalPrice = checkout(new BlackFridayDiscount(), 15000); // aucune condition dans checkout()

exercises.starterCode:
interface Discount { int apply(int total); }
class TenPercent implements Discount { public int apply(int total) { return total / 10; } }
public class Main {
    public static void main(String[] args) {
        Discount discount = new TenPercent();
        System.out.println("Remise: " + discount.apply(150));
    }
}
